def main():
    (OUT/'SA18_items.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
    entries=[]
    for item in rows:
        for j,s in enumerate(item['sources']):
            n=int(s.rsplit('#',1)[1]); verdict='merged into item '+item['id'] if j else 'kept as item '+item['id']
            if n in (7,27,33,41,52,53,55,60,63): verdict='corrected'
            entries.append(dict(entry_id=s,item_id=item['id'],verdict=verdict,reason=item['check_reason']+' '+item['reconstruction']))
    entries.sort(key=lambda e:int(e['entry_id'].split('#')[-1]))
    with (OUT/'SA18_entries.tsv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=['entry_id','item_id','verdict','reason'],delimiter='\t');w.writeheader();w.writerows(entries)
    assert [int(x['entry_id'].split('#')[-1]) for x in entries]==list(range(1,86))
    print(json.dumps({'items':len(rows),'entries':len(entries),'source':'manually adjudicated after whole-source reading','missing_entries':[]},indent=2))
if __name__=='__main__':main()
